style:
.dsh-pet-root[data-state="idle"] .p-body { animation: dsh-pg-bob 3s ease-in-out infinite; transform-origin: 100px 160px; }
.dsh-pet-root[data-state="happy"] .p-body { animation: dsh-pg-pop 0.6s cubic-bezier(0.34, 1.56, 0.64, 1); transform-origin: 100px 160px; }
.dsh-pet-root[data-state="sleep"] .p-body { animation: dsh-pg-float 3.6s ease-in-out infinite; transform-origin: 100px 160px; }
@keyframes dsh-pg-bob { 0%,100% { transform: translateY(0); } 50% { transform: translateY(-6px); } }
@keyframes dsh-pg-pop { 0% { transform: scale(1); } 45% { transform: scale(1.08, 0.94); } 100% { transform: scale(1); } }
@keyframes dsh-pg-float { 0%,100% { transform: translateY(0) rotate(-1deg); } 50% { transform: translateY(-8px) rotate(1deg); } }
.dsh-pet-root[data-state="happy"] .dsh-pet-expr[data-expr="happy"] { display: inline; }
.dsh-pet-root[data-state="happy"] .dsh-pet-expr[data-expr-default] { display: none; }
.dsh-pet-root[data-state="sleep"] .dsh-pet-expr[data-expr="sleep"] { display: inline; }
.dsh-pet-root[data-state="sleep"] .dsh-pet-expr[data-expr-default] { display: none; }
